// Diagnostique le problème de qualité d'un enregistrement.
// TODO : ne détecter que les valeurs manquantes laisse passer doublons et
//        types incohérents — vérifier missing, puis duplicate, puis type.
export function dataIssue(record) {
  if (record.value === null || record.value === undefined || record.value === '') return 'missing';
  return 'ok';
}

